INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine File-Share-Datenbank dasselbe wie eine relationale Datenbank?', 2, '[{"text": "No", "correct": true, "because": "Sharing vs. Struktur"}, {"text": "Yes", "correct": false, "because": "Different focus"}]'),
('00000000-0000-0000-0000-000000000000', 'What is the primary purpose of a file-share database?', 3, '[{"text": "Enable shared access to database files", "correct": true, "because": "Network collaboration"}, {"text": "Encrypt all data", "correct": false, "because": "Not primary"}, {"text": "Run hardware diagnostics", "correct": false, "because": "Not hardware-related"}]'),
('00000000-0000-0000-0000-000000000000', 'Which components are typical for a file-share database?', 5, '[{"text": "Network file system", "correct": true, "because": "SMB, NFS"}, {"text": "Shared storage", "correct": true, "because": "Data access"}, {"text": "Paper logs", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) File-share databases allow multiple users to access data. b) They require a dedicated server OS.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Flexible OS"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I ignore with a file-share database?', 4, '[{"text": "Network connectivity", "correct": false, "because": "Essential"}, {"text": "Access permissions", "correct": false, "because": "Security"}, {"text": "Paper size", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if a file-share database always uses a relational DBMS?', 2, '[{"text": "No", "correct": true, "because": "Also flat files"}, {"text": "Yes", "correct": false, "because": "Not mandatory"}]'),
('00000000-0000-0000-0000-000000000000', 'Which protocol is commonly used for file-share databases?', 3, '[{"text": "SMB", "correct": true, "because": "Server Message Block"}, {"text": "HTTP", "correct": false, "because": "Web protocol"}, {"text": "FTP", "correct": false, "because": "File transfer"}]'),
('00000000-0000-0000-0000-000000000000', 'What benefits does a file-share database offer?', 5, '[{"text": "Collaborative access", "correct": true, "because": "Multiple users"}, {"text": "Simplified sharing", "correct": true, "because": "Network-based"}, {"text": "High-speed printing", "correct": false, "because": "Not relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard: a) File-share databases support multi-user access. b) They’re only for large enterprises. Is that true?', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Any size"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What don’t I need for a file-share database?', 4, '[{"text": "Network connection", "correct": false, "because": "Sharing requires it"}, {"text": "File system", "correct": false, "because": "Data storage"}, {"text": "Physical paper", "correct": true, "because": "Digital sufficient"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Does a file-share database always require a server?', 2, '[{"text": "No", "correct": true, "because": "Peer-to-peer possible"}, {"text": "Yes", "correct": false, "because": "Flexible setup"}]'),
('00000000-0000-0000-0000-000000000000', 'Which systems use file-share databases?', 4, '[{"text": "LAN networks", "correct": true, "because": "Local sharing"}, {"text": "Cloud services", "correct": true, "because": "Remote access"}, {"text": "Typewriters", "correct": false, "because": "Not digital"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard that file-share databases are only for backups. Is that true?', 2, '[{"text": "No", "correct": true, "because": "Also active data"}, {"text": "Yes", "correct": false, "because": "Multiple uses"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I prioritize with a file-share database?', 3, '[{"text": "Access control", "correct": true, "because": "Security"}, {"text": "Paper type", "correct": false, "because": "Irrelevant"}, {"text": "Speed alone", "correct": false, "because": "Balance needed"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) File-share databases can use NFS. b) They’re only for single-user access.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Multi-user focus"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What challenges arise with file-share databases?', 5, '[{"text": "Concurrency issues", "correct": true, "because": "Multiple access"}, {"text": "Data consistency", "correct": true, "because": "Sync problems"}, {"text": "Paper jams", "correct": false, "because": "Not physical"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s unimportant for a file-share database?', 3, '[{"text": "Network protocol", "correct": false, "because": "Sharing method"}, {"text": "Access permissions", "correct": false, "because": "Security"}, {"text": "Font style", "correct": true, "because": "No impact"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Can a file-share database be cloud-based?', 3, '[{"text": "Yes", "correct": true, "because": "E.g., Google Drive"}, {"text": "No", "correct": false, "because": "Cloud possible"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if file-share databases support real-time collaboration?', 2, '[{"text": "Yes", "correct": true, "because": "With proper setup"}, {"text": "No", "correct": false, "because": "Possible"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s central to a file-share database?', 4, '[{"text": "Shared access", "correct": true, "because": "Core principle"}, {"text": "Local processing", "correct": false, "because": "Not primary"}, {"text": "Paper records", "correct": false, "because": "Irrelevant"}]');
